===ClientProjectsPanel===
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Project } from './ProjectsPage';

// A client's projects: the projects listing scoped to one client, rendered in the client-detail
// context. Server data is read with useQuery under the SAME ['projects'] key the projects page owns
// (so a project write that invalidates ['projects'] refreshes this too) and filtered to the client
// it is handed — never copied into state, never hand-maintained (rule 5). Reuses the
// project-row-<id>/project-name anchors inside its own client-projects-table.
export function ClientProjectsPanel({ clientId }: { clientId: number }) {
  const projects = useQuery({
    queryKey: ['projects'],
    queryFn: () => getJson<Project[]>('/api/projects'),
  });

  // Archived projects are tucked away everywhere: kept on the server but off this panel too.
  const rows = (projects.data ?? []).filter((p) => p.clientId === clientId && !p.archived);

  return (
    <section data-testid="client-projects">
      {rows.length === 0 ? (
        <p data-testid="client-projects-empty">No projects yet.</p>
      ) : (
        <table data-testid="client-projects-table">
          <thead>
            <tr>
              <th>Name</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((p) => (
              <tr key={p.id} data-testid={`project-row-${p.id}`}>
                <td data-testid="project-name">{p.name}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}
===showArchived.slot===
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

// The show-archived toggle — its own file, filling the projects toolbar slot. It OWNS the
// `showArchived` URL key (rule 4: a show/hide toggle outlives a click, so it lives in the URL, not
// useState). The projects page reads the same key to decide whether archived projects are listed;
// nothing is passed between them. Carries data-testid="projects-show-archived" (the test contract).
function ShowArchived() {
  const [showArchived, setShowArchived] = useSearchParam('showArchived', asFlag);
  return (
    <button
      type="button"
      data-testid="projects-show-archived"
      aria-pressed={showArchived}
      onClick={() => setShowArchived(showArchived ? undefined : true)}
    >
      {showArchived ? 'Hide archived' : 'Show archived'}
    </button>
  );
}

export const contribution = ProjectsToolbar.fill({ order: 10, Component: ShowArchived });
===statusFilter.slot===
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { PROJECT_STATUSES } from './ProjectsPage';

// The by-status project filter — its own file, filling the projects toolbar slot (order 30, after
// the show-archived toggle at 10 and the tag filter at 20). It OWNS the `projectStatus` URL key
// (rule 4: a filter outlives a click, so it lives in the URL, not useState). The projects page reads
// the same key and narrows its rows to projects at that status; nothing is passed between them.
// Carries data-testid="project-status-filter" (the test contract); the empty option clears the key,
// showing every project again.
function StatusFilter() {
  const [status, setStatus] = useSearchParam('projectStatus', asString);
  return (
    <select
      data-testid="project-status-filter"
      value={status}
      onChange={(e) => setStatus(e.target.value || undefined)}
    >
      <option value="">All statuses</option>
      {PROJECT_STATUSES.map((s) => (
        <option key={s} value={s}>
          {s}
        </option>
      ))}
    </select>
  );
}

export const contribution = ProjectsToolbar.fill({ order: 30, Component: StatusFilter });

